CREATE FUNCTION touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TABLE locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, jurisdiction text NOT NULL DEFAULT 'NZ' CHECK(jurisdiction IN ('NZ','AU')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE technicians (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, weekly_hours numeric NOT NULL DEFAULT 40 CHECK(weekly_hours>0), rate numeric NOT NULL DEFAULT 0 CHECK(rate>=0), currency text NOT NULL DEFAULT 'NZD' CHECK(currency IN ('NZD','AUD','USD')), competency_ref text, competency_until date, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), external_id text UNIQUE, name text NOT NULL, location_id uuid REFERENCES locations, serial text, criticality text NOT NULL DEFAULT 'medium' CHECK(criticality IN ('low','medium','high')), status text NOT NULL DEFAULT 'operational' CHECK(status IN ('operational','down','retired')), inspection_due date, interval_source text, isolation_required boolean NOT NULL DEFAULT true, registered_plant boolean NOT NULL DEFAULT false, registration_ref text, source_data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE meters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, asset_id uuid NOT NULL REFERENCES assets, unit text NOT NULL DEFAULT 'hours', value numeric NOT NULL DEFAULT 0 CHECK(value>=0), read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, asset_id uuid NOT NULL REFERENCES assets, interval_days integer NOT NULL CHECK(interval_days>0), next_due date NOT NULL, meter_id uuid REFERENCES meters, meter_interval numeric CHECK(meter_interval>0), next_meter numeric CHECK(next_meter>=0), instructions text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK((meter_id IS NULL AND meter_interval IS NULL AND next_meter IS NULL) OR (meter_id IS NOT NULL AND meter_interval IS NOT NULL AND next_meter IS NOT NULL)));
CREATE TABLE work_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), external_id text UNIQUE, title text NOT NULL, asset_id uuid REFERENCES assets, technician_id uuid REFERENCES technicians, schedule_id uuid REFERENCES schedules, due_date date, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','on_hold','done','cancelled')), priority text NOT NULL DEFAULT 'medium' CHECK(priority IN ('none','low','medium','high','urgent')), work_type text NOT NULL DEFAULT 'reactive' CHECK(work_type IN ('reactive','preventive','other')), estimated_hours numeric NOT NULL DEFAULT 1 CHECK(estimated_hours>=0), description text NOT NULL DEFAULT '', isolation_ref text, completion_note text, completed_at timestamptz, source_data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(status<>'done' OR completed_at IS NOT NULL));
CREATE UNIQUE INDEX one_active_schedule_work ON work_orders(schedule_id) WHERE status NOT IN ('done','cancelled');
CREATE TABLE procedure_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_order_id uuid NOT NULL REFERENCES work_orders, name text NOT NULL, result text NOT NULL DEFAULT 'pending' CHECK(result IN ('pending','pass','fail','na')), evidence text, checked_by text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, asset_id uuid NOT NULL REFERENCES assets, requested_by text NOT NULL, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','approved','declined')), work_order_id uuid REFERENCES work_orders, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, sku text NOT NULL UNIQUE, stock numeric NOT NULL DEFAULT 0 CHECK(stock>=0), reorder_point numeric NOT NULL DEFAULT 0 CHECK(reorder_point>=0), unit_cost numeric NOT NULL DEFAULT 0 CHECK(unit_cost>=0), currency text NOT NULL DEFAULT 'NZD' CHECK(currency IN ('NZD','AUD','USD')), supplier text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE part_uses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_order_id uuid NOT NULL REFERENCES work_orders, part_id uuid NOT NULL REFERENCES parts, quantity numeric NOT NULL CHECK(quantity>0), unit_cost numeric NOT NULL CHECK(unit_cost>=0), currency text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, part_id uuid NOT NULL REFERENCES parts, quantity numeric NOT NULL CHECK(quantity>0), unit_cost numeric NOT NULL CHECK(unit_cost>=0), currency text NOT NULL, supplier text NOT NULL, expected_date date NOT NULL, status text NOT NULL DEFAULT 'ordered' CHECK(status IN ('ordered','received')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE labour (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_order_id uuid NOT NULL REFERENCES work_orders, technician_id uuid NOT NULL REFERENCES technicians, hours numeric NOT NULL CHECK(hours>0), rate numeric NOT NULL CHECK(rate>=0), currency text NOT NULL, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE downtime (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES assets, started_at timestamptz NOT NULL, ended_at timestamptz, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(ended_at IS NULL OR ended_at>started_at));
CREATE UNIQUE INDEX one_active_downtime ON downtime(asset_id) WHERE ended_at IS NULL;
CREATE TABLE inspections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES assets, inspector text NOT NULL, inspected_on date NOT NULL, next_due date NOT NULL, result text NOT NULL CHECK(result IN ('pass','fail')), evidence text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(next_due>inspected_on));
CREATE TABLE activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_order_id uuid NOT NULL REFERENCES work_orders, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), action text NOT NULL, record_id text, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['locations','technicians','assets','meters','schedules','work_orders','procedure_steps','requests','parts','part_uses','purchase_orders','labour','downtime','inspections','activity','audit'] LOOP EXECUTE format('CREATE TRIGGER touch BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION touch_updated_at()',t); END LOOP; END $$;
CREATE VIEW v_work AS SELECT w.id,w.title,a.name AS asset,l.name AS location,a.criticality,t.name AS technician,w.status,w.priority,w.work_type,w.due_date,w.estimated_hours,COALESCE((SELECT sum(hours) FROM labour WHERE work_order_id=w.id),0) AS logged_hours, w.completed_at, w.created_at, w.updated_at FROM work_orders w LEFT JOIN assets a ON a.id=w.asset_id LEFT JOIN locations l ON l.id=a.location_id LEFT JOIN technicians t ON t.id=w.technician_id;
CREATE VIEW v_attention AS SELECT id,title,asset,technician,status,priority,due_date,concat_ws('; ',CASE WHEN due_date<current_date THEN 'overdue' END,CASE WHEN due_date IS NULL THEN 'no due date' END,CASE WHEN technician IS NULL THEN 'unassigned' END,CASE WHEN updated_at<now()-interval '7 days' THEN 'quiet over 7 days' END,CASE WHEN status='on_hold' THEN 'on hold' END) AS reason FROM v_work WHERE status NOT IN ('done','cancelled') AND (due_date<current_date OR due_date IS NULL OR technician IS NULL OR updated_at<now()-interval '7 days' OR status='on_hold');
CREATE VIEW v_pm_due AS SELECT s.id,s.name,a.name AS asset,s.next_due,m.value AS meter_value,s.next_meter,s.instructions,EXISTS(SELECT 1 FROM work_orders w WHERE w.schedule_id=s.id AND w.status NOT IN ('done','cancelled')) AS has_open_work FROM schedules s JOIN assets a ON a.id=s.asset_id LEFT JOIN meters m ON m.id=s.meter_id WHERE s.active AND a.status<>'retired' AND (s.next_due<=current_date+7 OR m.value>=s.next_meter);
CREATE VIEW v_costs AS SELECT w.id,w.title,a.name AS asset,c.currency,sum(c.amount)::numeric(14,2) AS total_cost FROM (SELECT work_order_id,currency,hours*rate AS amount FROM labour UNION ALL SELECT work_order_id,currency,quantity*unit_cost FROM part_uses) c JOIN work_orders w ON w.id=c.work_order_id LEFT JOIN assets a ON a.id=w.asset_id GROUP BY w.id,w.title,a.name,c.currency;
